"use client";
/**
 * Clio toggle: a tile with one switch. Turned on, the tile takes Clio's dark focus state on its own, with a soft
 * light gathering in its corner, while the board around it stays paper.
 */
import { type ButtonHTMLAttributes, type ReactNode, useId, useState } from "react";
import { ClioTile, type ClioTileProps } from "./theme";

const SWITCH_CSS = `
.clio-switch{all:unset;position:relative;flex:none;display:inline-flex;align-items:center;width:40px;height:24px;border-radius:999px;cursor:pointer;background:var(--clio-hairline-strong);box-shadow:inset 0 1px 2px rgb(0 0 0 / .12);transition:background-color 260ms var(--clio-mode-ease);-webkit-tap-highlight-color:transparent}
.clio-switch[aria-checked="true"]{background:var(--clio-accent)}
.clio-switch:hover{background:var(--clio-ink-tertiary)}
.clio-switch[aria-checked="true"]:hover{background:var(--clio-accent-hover)}
.clio-switch:active .clio-switch__thumb{width:23px}
.clio-switch[aria-checked="true"]:active .clio-switch__thumb{transform:translate3d(13px,0,0)}
.clio-switch:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-switch__thumb{position:absolute;left:3px;top:3px;width:18px;height:18px;border-radius:999px;background:#fff;box-shadow:0 1px 2px rgb(0 0 0 / .22),0 2px 6px -2px rgb(0 0 0 / .25);transition:transform 300ms cubic-bezier(.34,1.3,.64,1),width 160ms var(--clio-press-ease)}
.clio-switch[aria-checked="true"] .clio-switch__thumb{transform:translate3d(16px,0,0)}
.clio-switch[data-size="sm"]{width:34px;height:20px}
.clio-switch[data-size="sm"] .clio-switch__thumb{width:14px;height:14px}
.clio-switch[data-size="sm"][aria-checked="true"] .clio-switch__thumb{transform:translate3d(14px,0,0)}
@media (prefers-reduced-motion:reduce){.clio-switch__thumb{transition:none}}
`;

const TOGGLE_CSS = `
.clio-toggle__body{margin-top:auto;display:flex;flex-direction:column;gap:8px;padding-top:12px}
.clio-toggle__state{position:relative;height:40px;font-size:40px;overflow:hidden}
.clio-toggle__word{display:block;animation:clio-toggle-word 520ms var(--clio-alive-ease) both}
@keyframes clio-toggle-word{from{opacity:0;transform:translate3d(0,60%,0)}to{opacity:1;transform:none}}
.clio-toggle__detail{min-height:2.8em}
@media (prefers-reduced-motion:reduce){.clio-toggle__word{animation:none}}
`;

export interface ClioSwitchProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value" | "role"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  /** The switch's name for assistive tech when nothing visible names it. */
  label?: string;
  size?: "md" | "sm";
}

/** A switch: role="switch" with aria-checked, controlled or not. */
export function ClioSwitch({
  checked,
  defaultChecked = false,
  onCheckedChange,
  label,
  size = "md",
  className,
  onClick,
  ...rest
}: ClioSwitchProps) {
  const [own, setOwn] = useState(defaultChecked);
  const on = checked ?? own;
  return (
    <>
      <style>{SWITCH_CSS}</style>
      <button
        {...rest}
        type="button"
        role="switch"
        aria-checked={on}
        aria-label={rest["aria-labelledby"] ? undefined : label}
        data-size={size}
        className={className ? `clio-switch ${className}` : "clio-switch"}
        onClick={(event) => {
          onClick?.(event);
          if (event.defaultPrevented) return;
          if (checked === undefined) setOwn(!on);
          onCheckedChange?.(!on);
        }}
      >
        <span className="clio-switch__thumb" aria-hidden="true" />
      </button>
    </>
  );
}

export interface ClioToggleProps extends Omit<ClioTileProps, "children" | "label" | "tone"> {
  /** Names the tile and the switch. */
  label?: string;
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  onText?: ReactNode;
  offText?: ReactNode;
  /** The line under the state, on and off. */
  detailOn?: ReactNode;
  detailOff?: ReactNode;
  /** Take the dark focus state while on. */
  darkWhenOn?: boolean;
}

export function ClioToggle({
  label = "Quiet hours",
  checked,
  defaultChecked = false,
  onCheckedChange,
  onText = "On",
  offText = "Off",
  detailOn = "Nudges wait until 21:00",
  detailOff = "Nudges arrive as usual",
  darkWhenOn = true,
  className,
  ...tile
}: ClioToggleProps) {
  const [own, setOwn] = useState(defaultChecked);
  const on = checked ?? own;
  const detailId = useId();
  const set = (next: boolean) => {
    if (checked === undefined) setOwn(next);
    onCheckedChange?.(next);
  };
  return (
    <ClioTile
      {...tile}
      label={label}
      meta={
        <ClioSwitch checked={on} onCheckedChange={set} label={label} aria-describedby={detailId} />
      }
      tone={on && darkWhenOn ? "focus" : "inherit"}
      glow={on && darkWhenOn}
      className={className ? `clio-toggle ${className}` : "clio-toggle"}
      data-on={on ? "" : undefined}
    >
      <style>{TOGGLE_CSS}</style>
      <div className="clio-toggle__body">
        <p className="clio-numeral clio-toggle__state" aria-hidden="true">
          <span key={on ? "on" : "off"} className="clio-toggle__word">
            {on ? onText : offText}
          </span>
        </p>
        <p id={detailId} className="clio-caption clio-toggle__detail">
          {on ? detailOn : detailOff}
        </p>
      </div>
    </ClioTile>
  );
}
